def range_sums(a, queries):
    """一维前缀和:pre[0]=0,pre[i]=a[0..i-1] 之和;
    闭区间 [l, r] 的和 = pre[r+1] - pre[l]。预处理 O(n),每次查询 O(1)。"""
    n = len(a)
    pre = [0] * (n + 1)
    for i in range(n):
        pre[i + 1] = pre[i] + a[i]
    res = []
    for l, r in queries:
        res.append(pre[r + 1] - pre[l])
    return res
